#!/bin/bash
# ============================================================================
# GLM-5.3 Decode node launcher (shared by D0 and D1)
# ============================================================================
# Do NOT edit this file. Configure the deployment in start_d.sh and pass D0 or D1.
#
# Tested with vLLM 0.30.0 / vllm-ascend 0.30.0 / CANN 9.2.0 on Ascend950DT,
# 8 devices per node, 2P2D topology (2 prefill + 2 decode nodes).
# ============================================================================

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source ~/.bashrc 2>/dev/null || true

# ===================== Model and log paths =====================
export MODEL_PATH=${MODEL_PATH:-/data/models/GLM-5.3-w4a4c4-mxfp4}
export MODEL_NAME=${MODEL_NAME:-glm}
export LOG_PATH=${LOG_PATH:-/data/logs/glm-53/1p1d}
export VLLM_PROFILER_DIR=${VLLM_PROFILER_DIR:-/data/profiling}
mkdir -p "${LOG_PATH}"

# ===================== Ascend environment =====================
export ASCEND_VLLM_PATH=${ASCEND_VLLM_PATH:-/home/ma-user/AscendCloud/AscendCloud-LLM/llm_inference/ascend_vllm}
export VLLM_PLUGINS=${VLLM_PLUGINS:-ascend_vllm,modelarts_ascend_kv_connector,ascend_model_loader,ascend_service_profiling,ascend_model,modelarts_general_plugin_patch}
export PYTORCH_NPU_ALLOC_CONF=${PYTORCH_NPU_ALLOC_CONF:-expandable_segments:True}
export TASK_QUEUE_ENABLE=${TASK_QUEUE_ENABLE:-1}
export VLLM_ASCEND_ENABLE_NZ=${VLLM_ASCEND_ENABLE_NZ:-0}
export VLLM_USE_FASTOKENS=${VLLM_USE_FASTOKENS:-1}
export VLLM_SERVER_DEV_MODE=${VLLM_SERVER_DEV_MODE:-1}
export NOT_ALLOWED_COMPLETIONS=${NOT_ALLOWED_COMPLETIONS:-1}
export ASCEND_TRANSFER_TIMEOUT=${ASCEND_TRANSFER_TIMEOUT:-6000}
export VLLM_ENGINE_READY_TIMEOUT_S=${VLLM_ENGINE_READY_TIMEOUT_S:-300000}
export ASCEND_PROCESS_LOG_PATH=${ASCEND_PROCESS_LOG_PATH:-${LOG_PATH}}
export VALIDATORS_CONFIG_PATH=${VALIDATORS_CONFIG_PATH:-/home/ma-user/AscendCloud/AscendCloud-LLM/llm_inference/ascend_vllm/ascend_vllm/middleware/validator_config_glm.json}

# Rotating file handler: vLLM logs go through ConcurrentRotatingFileHandler,
# so server_d.log rotates instead of growing without bound. stdout/stderr keeps
# its own file below to survive failures before the handler is configured.
export LOG_UPDATE_CONFIG_PATH=${LOG_UPDATE_CONFIG_PATH:-${ASCEND_VLLM_PATH}/../../llm_tools/logging/update_logging_config.py}
export VLLM_LOGGING_CONFIG_PATH=$(python "${LOG_UPDATE_CONFIG_PATH}" --logging-file-name "${LOG_PATH}/server_d.log")

# Decode nodes do not use FlashComm1, but they do use the same helpers.
export ENABLE_ZERO_BUBBLE=${ENABLE_ZERO_BUBBLE:-1}
export ENABLE_ASYNC_REJECT_SAMPLE=${ENABLE_ASYNC_REJECT_SAMPLE:-1}
export ASCEND_VLLM_REUSE_PREFILLED_TOKENS=${ASCEND_VLLM_REUSE_PREFILLED_TOKENS:-1}
export ASCEND_VLLM_SKIP_DECODE_TOKENIZE=${ASCEND_VLLM_SKIP_DECODE_TOKENIZE:-1}
export REQUEST_PD_ROLE=decode

# ===================== HCCL =====================
# Decode uses a smaller buffer: 16 data-parallel workers share one node.
export HCCL_BUFFSIZE=${HCCL_BUFFSIZE:-800}
export HCCL_CONNECT_TIMEOUT=${HCCL_CONNECT_TIMEOUT:-600}
export HCCL_EXEC_TIMEOUT=${HCCL_EXEC_TIMEOUT:-600}
export HCCL_ALGO=${HCCL_ALGO:-level0:fullmesh}
export HCCL_OP_EXPANSION_MODE=${HCCL_OP_EXPANSION_MODE:-CCU_SCHED}
export OMP_PROC_BIND=${OMP_PROC_BIND:-false}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-10}

# ===================== Network configuration =====================
# NETWORK_CARD_NAME is required: HCCL/GLOO must bind to the RoCE interface,
# not to an arbitrary interface picked by the runtime.
export NETWORK_CARD_NAME=${NETWORK_CARD_NAME:-xxx}
export LOCAL_IP=${LOCAL_IP:-$(hostname -I | awk '{print $1}')}
export HCCL_IF_IP=$LOCAL_IP
export GLOO_SOCKET_IFNAME=$NETWORK_CARD_NAME
export TP_SOCKET_IFNAME=$NETWORK_CARD_NAME
export HCCL_SOCKET_IFNAME=$NETWORK_CARD_NAME

# ===================== Mooncake =====================
export MOONCAKE_CONFIG_PATH=${MOONCAKE_CONFIG_PATH:-${SCRIPT_DIR}/mooncake.json}

# ===================== Parallelism =====================
# Decode runs TP=1 and DP=16 across two nodes: 8 local ranks per node.
export DP_SIZE=${DP_SIZE:-16}
export DP_SIZE_LOCAL=${DP_SIZE_LOCAL:-8}
export DP_RANK_START=${DP_RANK_START:-0}
export DP_ADDRESS=${DP_ADDRESS:-$LOCAL_IP}
export TP_SIZE=${TP_SIZE:-1}

# ===================== Serving =====================
export SERVE_PORT=${SERVE_PORT:-8667}
export MAX_MODEL_LEN=${MAX_MODEL_LEN:-204800}
export MAX_NUM_BATCHED_TOKENS=${MAX_NUM_BATCHED_TOKENS:-32}
export MAX_NUM_SEQS=${MAX_NUM_SEQS:-8}
export GPU_MEMORY_UTILIZATION=${GPU_MEMORY_UTILIZATION:-0.85}
export NUM_SPECULATIVE_TOKENS=${NUM_SPECULATIVE_TOKENS:-3}

# ===================== KV transfer =====================
export KV_PORT=${KV_PORT:-30300}
export ENGINE_ID=${ENGINE_ID:-3}
export KV_PREFILL_DP_SIZE=${KV_PREFILL_DP_SIZE:-2}
export KV_PREFILL_TP_SIZE=${KV_PREFILL_TP_SIZE:-8}
export KV_DECODE_DP_SIZE=${KV_DECODE_DP_SIZE:-16}
export KV_DECODE_TP_SIZE=${KV_DECODE_TP_SIZE:-1}

# The KV transfer config is assembled in a variable first. vLLM receives it
# as one argument, so the values have to be expanded by bash beforehand.
# Single-quoting the literal JSON would pass an unexpanded ${...} through
# and vLLM would reject it as invalid JSON.
KV_TRANSFER_CONFIG="{
  \"engine_id\": \"${ENGINE_ID}\",
  \"kv_connector\": \"MultiConnector\",
  \"kv_connector_extra_config\": {
    \"ascend_local_comm_res_path\": \"/etc/hixlep\",
    \"connectors\": [
      {
        \"kv_connector\": \"MooncakeConnectorV1\",
        \"kv_connector_extra_config\": {
          \"prefill\": { \"dp_size\": ${KV_PREFILL_DP_SIZE}, \"tp_size\": ${KV_PREFILL_TP_SIZE} },
          \"decode\": { \"dp_size\": ${KV_DECODE_DP_SIZE}, \"tp_size\": ${KV_DECODE_TP_SIZE} },
          \"use_ascend_direct\": true,
          \"ascend_local_comm_res_path\": \"/etc/hixlep\"
        },
        \"kv_port\": \"${KV_PORT}\",
        \"kv_role\": \"kv_consumer\"
      },
      {
        \"kv_connector\": \"AscendStoreConnector\",
        \"kv_connector_extra_config\": {
          \"backend\": \"mooncake\",
          \"lookup_rpc_port\": \"0\",
          \"ascend_local_comm_res_path\": \"/etc/hixlep\"
        },
        \"kv_role\": \"kv_consumer\"
      }
    ]
  },
  \"kv_load_failure_policy\": \"recompute\",
  \"kv_role\": \"kv_consumer\"
}"

echo "=============================================="
echo "GLM-5.3 Decode node"
echo "=============================================="
echo "Model path      : ${MODEL_PATH}"
echo "Served name     : ${MODEL_NAME}"
echo "Local IP        : ${LOCAL_IP}"
echo "NIC name        : ${NETWORK_CARD_NAME}"
echo "DP size         : ${DP_SIZE}"
echo "DP size local   : ${DP_SIZE_LOCAL}"
echo "DP start rank   : ${DP_RANK_START}"
echo "DP address      : ${DP_ADDRESS}"
echo "TP size         : ${TP_SIZE}"
echo "Serve port      : ${SERVE_PORT}"
echo "Max model len   : ${MAX_MODEL_LEN}"
echo "Log path        : ${LOG_PATH}"
echo "=============================================="

# ===================== Launch vLLM =====================
nohup vllm serve "${MODEL_PATH}" \
  --host 0.0.0.0 \
  --api-server-count 1 \
  --port ${SERVE_PORT} \
  --middleware=ascend_vllm.middleware.param_check.ValidateSamplingParams \
  --max_model_len ${MAX_MODEL_LEN} \
  --max-num-batched-tokens ${MAX_NUM_BATCHED_TOKENS} \
  --served-model-name ${MODEL_NAME} \
  --gpu-memory-utilization ${GPU_MEMORY_UTILIZATION} \
  --tensor-parallel-size ${TP_SIZE} \
  --data-parallel-size ${DP_SIZE} \
  --data-parallel-size-local ${DP_SIZE_LOCAL} \
  --data-parallel-start-rank ${DP_RANK_START:-0} \
  --data-parallel-address ${DP_ADDRESS} \
  --max-num-seqs ${MAX_NUM_SEQS} \
  --async-scheduling \
  --enable-expert-parallel \
  --quantization ascend \
  --enable-prefix-caching \
  --enable-prompt-tokens-details \
  --enable-auto-tool-choice \
  --tool-call-parser glm47 \
  --reasoning-parser glm47 \
  --speculative-config "{\"num_speculative_tokens\": ${NUM_SPECULATIVE_TOKENS}, \"method\": \"deepseek_mtp\", \"enforce_eager\": true}" \
  --compilation-config '{"cudagraph_mode": "FULL_DECODE_ONLY"}' \
  --profiler-config "{\"profiler\": \"torch\", \"torch_profiler_dir\": \"${VLLM_PROFILER_DIR}\", \"torch_profiler_with_stack\": true, \"delay_iterations\": 100, \"max_iterations\": 3, \"ignore_frontend\": true}" \
  --kv-transfer-config "${KV_TRANSFER_CONFIG}" \
  --kv-cache-dtype fp8 \
  --attention-config '{"indexer_kv_dtype": "mxfp4", "mla_kv_quant_mode": "mxfp4"}' \
  --additional_config '{"enable_cpu_binding": true, "recompute_scheduler_enable": true, "multistream_overlap_shared_expert": true, "enable_dsa_cp": false, "enable_flashcomm1": true, "enable_fused_mc2": 0, "sfa_recent128": {"window": 128, "reader": "single_pass", "single_pass_kernel": "kv_split4", "source_root": "/tmp/mxllm-split4-experiment", "library_dir": "/tmp/qsfa-kv-split-build", "diagnostics_path": "/tmp/sfa_diagnostics/layers"}}' \
  > "${LOG_PATH}/server_d.console.log" 2>&1 &

echo "=============================================="
echo "Decode node started in background. PID: $!"
echo "Log: tail -f ${LOG_PATH}/server_d.log"
echo "=============================================="
